create table eba_demo_appr_laptop_requests (
    id                      number
        generated by default on null as identity
    not null enable,
    empno                   number not null enable,
    status                  varchar2(16 byte) default 'PENDING' not null enable,
    decision_date           date,
    approver                varchar2(80 byte),
    approval_task_id        number,
    workflow_id             number,
    laptop_type             varchar2(10 byte),
    need_by                 date,
    order_date              date,
    order_id                number(10, 0),
    delivered_date          date,
    delivery_action_task_id number
)
    rowdependencies;

alter table eba_demo_appr_laptop_requests
    add constraint laptop_request_status_ck
        check ( status in ( 'APPROVED', 'REJECTED', 'PENDING', 'DELIVERED' ) ) enable;


